mapper.select:
SELECT d.id, d.name, d.phone, d.license_no, d.tractor_id, d.company_id, d.status, d.create_time, c.name AS companyName, t.plate_no AS plateNo FROM driver d LEFT JOIN transport_company c ON c.id = d.company_id LEFT JOIN tractor t ON t.id = d.tractor_id
AND d.name LIKE CONCAT('%', #{name}, '%')
AND d.phone LIKE CONCAT('%', #{phone}, '%')
AND d.company_id = #{companyId}
ORDER BY d.id ASC LIMIT #{offset}, #{size}

mapper.update:
UPDATE driver
name = #{name}, phone = #{phone}, license_no = #{licenseNo}, tractor_id = #{tractorId}, company_id = #{companyId}, status = #{status},
WHERE id = #{id}
